const std = @import("std");

/// Compact AST for the REA-derived room-action rules extracted from HEXUMA.OVR.
/// The JSON is generated by scripts/extract_overlay_rules.py from the eleven
/// decompiled overlay entry routines. It is data, not hand-written game logic.
pub const Expr = union(enum) {
    number: i64,
    variable: []const u8,
    flag: []const u8,
    unary: struct { op: []const u8, child: *Expr },
    binary: struct { op: []const u8, left: *Expr, right: *Expr },
    call: struct { name: []const u8, args: []*Expr },
    raw: []const u8,
};

pub const Value = union(enum) {
    number: i64,
    expr: *Expr,
};

pub const Target = union(enum) {
    variable: []const u8,
    flag: []const u8,
};

pub const Action = union(enum) {
    message: i64,
    picture: i64,
    dialog,
    clear_input,
    set: struct { target: Target, value: Value },
    add: struct { target: Target, value: i64 },
    return_,
};

pub const Rule = struct {
    when: *Expr,
    actions: []Action,
};

pub const RoomRange = struct {
    first: i64,
    last: i64,
};

pub const Unit = struct {
    unit: i64,
    rooms: []const u8,
    room_ranges: []RoomRange,
    rules: []Rule,

    pub fn containsRoom(self: Unit, room: i64) bool {
        for (self.room_ranges) |range| {
            if (range.first <= room and room <= range.last) return true;
        }
        return false;
    }
};

pub const Database = struct {
    units: []Unit,
};

pub fn parse(allocator: std.mem.Allocator, bytes: []const u8) !Database {
    const root = try std.json.parseFromSliceLeaky(std.json.Value, allocator, bytes, .{});
    const obj = asObject(root) orelse return error.InvalidOverlayRules;
    const units_value = obj.get("units") orelse return error.InvalidOverlayRules;
    const units_array = asArray(units_value) orelse return error.InvalidOverlayRules;
    const units = try allocator.alloc(Unit, units_array.items.len);
    for (units_array.items, 0..) |item, i| {
        const unit_obj = asObject(item) orelse return error.InvalidOverlayRules;
        const rules_value = unit_obj.get("rules") orelse return error.InvalidOverlayRules;
        const rules_array = asArray(rules_value) orelse return error.InvalidOverlayRules;
        const room_ranges = try parseRoomRanges(allocator, unit_obj.get("room_ranges"));
        const rules = try allocator.alloc(Rule, rules_array.items.len);
        for (rules_array.items, 0..) |rule_item, j| {
            const rule_obj = asObject(rule_item) orelse return error.InvalidOverlayRules;
            rules[j] = .{
                .when = try parseExpr(allocator, rule_obj.get("when") orelse return error.InvalidOverlayRules),
                .actions = try parseActions(allocator, rule_obj.get("actions") orelse return error.InvalidOverlayRules),
            };
        }
        units[i] = .{
            .unit = objectInt(unit_obj, "unit"),
            .rooms = objectString(unit_obj, "rooms"),
            .room_ranges = room_ranges,
            .rules = rules,
        };
    }
    return .{ .units = units };
}

fn parseRoomRanges(allocator: std.mem.Allocator, value: ?std.json.Value) ![]RoomRange {
    const arr = asArray(value orelse return &.{}) orelse return &.{};
    const ranges = try allocator.alloc(RoomRange, arr.items.len);
    for (arr.items, 0..) |item, i| {
        const pair = asArray(item) orelse return error.InvalidOverlayRules;
        ranges[i] = .{
            .first = if (pair.items.len > 0) objectIntFromValue(pair.items[0]) else 0,
            .last = if (pair.items.len > 1) objectIntFromValue(pair.items[1]) else 0,
        };
    }
    return ranges;
}

fn objectIntFromValue(value: std.json.Value) i64 {
    return switch (value) {
        .integer => |n| n,
        .float => |n| @intFromFloat(n),
        .number_string => |s| std.fmt.parseInt(i64, s, 10) catch 0,
        else => 0,
    };
}

fn asObject(value: std.json.Value) ?std.json.ObjectMap {
    return switch (value) {
        .object => |o| o,
        else => null,
    };
}

fn asArray(value: std.json.Value) ?std.json.Array {
    return switch (value) {
        .array => |a| a,
        else => null,
    };
}

fn objectString(obj: std.json.ObjectMap, key: []const u8) []const u8 {
    const value = obj.get(key) orelse return "";
    return switch (value) {
        .string => |s| s,
        else => "",
    };
}

fn objectInt(obj: std.json.ObjectMap, key: []const u8) i64 {
    const value = obj.get(key) orelse return 0;
    return switch (value) {
        .integer => |n| n,
        .float => |n| @intFromFloat(n),
        .number_string => |s| std.fmt.parseInt(i64, s, 10) catch 0,
        else => 0,
    };
}

fn dupString(allocator: std.mem.Allocator, value: std.json.Value) ![]const u8 {
    return switch (value) {
        .string => |s| try allocator.dupe(u8, s),
        else => "",
    };
}

fn parseExpr(allocator: std.mem.Allocator, value: std.json.Value) !*Expr {
    const obj = asObject(value) orelse return error.InvalidOverlayExpr;
    const node = try allocator.create(Expr);
    if (obj.get("n") != null) {
        node.* = .{ .number = objectInt(obj, "n") };
        return node;
    }
    if (obj.get("v")) |v| {
        node.* = .{ .variable = try dupString(allocator, v) };
        return node;
    }
    if (obj.get("flag")) |v| {
        node.* = .{ .flag = try dupString(allocator, v) };
        return node;
    }
    if (obj.get("raw")) |v| {
        node.* = .{ .raw = try dupString(allocator, v) };
        return node;
    }
    if (obj.get("u")) |op_value| {
        const child_value = obj.get("a") orelse return error.InvalidOverlayExpr;
        node.* = .{
            .unary = .{
                .op = try dupString(allocator, op_value),
                .child = try parseExpr(allocator, child_value),
            },
        };
        return node;
    }
    if (obj.get("b")) |op_value| {
        const left = obj.get("a") orelse return error.InvalidOverlayExpr;
        const right = obj.get("c") orelse return error.InvalidOverlayExpr;
        node.* = .{
            .binary = .{
                .op = try dupString(allocator, op_value),
                .left = try parseExpr(allocator, left),
                .right = try parseExpr(allocator, right),
            },
        };
        return node;
    }
    if (obj.get("call")) |name_value| {
        const args_value = obj.get("args") orelse return error.InvalidOverlayExpr;
        const args_json = asArray(args_value) orelse return error.InvalidOverlayExpr;
        const args = try allocator.alloc(*Expr, args_json.items.len);
        for (args_json.items, 0..) |arg, i| args[i] = try parseExpr(allocator, arg);
        node.* = .{
            .call = .{
                .name = try dupString(allocator, name_value),
                .args = args,
            },
        };
        return node;
    }
    node.* = .{ .number = 0 };
    return node;
}

fn parseValue(allocator: std.mem.Allocator, value: std.json.Value) !Value {
    return switch (value) {
        .integer => |n| .{ .number = n },
        .float => |n| .{ .number = @intFromFloat(n) },
        .number_string => |s| .{ .number = std.fmt.parseInt(i64, s, 10) catch 0 },
        .object => .{ .expr = try parseExpr(allocator, value) },
        else => .{ .number = 0 },
    };
}

fn parseTarget(allocator: std.mem.Allocator, value: std.json.Value) !Target {
    const text = switch (value) {
        .string => |s| s,
        else => return error.InvalidOverlayAction,
    };
    if (std.mem.startsWith(u8, text, "0x")) return .{ .flag = try allocator.dupe(u8, text) };
    return .{ .variable = try allocator.dupe(u8, text) };
}

fn parseActions(allocator: std.mem.Allocator, value: std.json.Value) ![]Action {
    const arr = asArray(value) orelse return error.InvalidOverlayAction;
    const actions = try allocator.alloc(Action, arr.items.len);
    for (arr.items, 0..) |item, i| {
        const obj = asObject(item) orelse return error.InvalidOverlayAction;
        const op = objectString(obj, "op");
        if (std.mem.eql(u8, op, "msg")) {
            actions[i] = .{ .message = objectInt(obj, "id") };
        } else if (std.mem.eql(u8, op, "picture")) {
            actions[i] = .{ .picture = objectInt(obj, "id") };
        } else if (std.mem.eql(u8, op, "dialog")) {
            actions[i] = .dialog;
        } else if (std.mem.eql(u8, op, "clear_input")) {
            actions[i] = .clear_input;
        } else if (std.mem.eql(u8, op, "return")) {
            actions[i] = .return_;
        } else if (std.mem.eql(u8, op, "set")) {
            actions[i] = .{
                .set = .{
                    .target = try parseTarget(allocator, obj.get("addr") orelse return error.InvalidOverlayAction),
                    .value = try parseValue(allocator, obj.get("value") orelse return error.InvalidOverlayAction),
                },
            };
        } else if (std.mem.eql(u8, op, "add")) {
            actions[i] = .{
                .add = .{
                    .target = try parseTarget(allocator, obj.get("addr") orelse return error.InvalidOverlayAction),
                    .value = objectInt(obj, "value"),
                },
            };
        } else {
            actions[i] = .clear_input;
        }
    }
    return actions;
}
